+static void fts5ExtractValueFromColumn(
+  sqlite3_context *pCtx,
+  Fts5Config *pConfig, 
+  sqlite3_value *pVal
+){
+  if( sqlite3_value_type(pVal)==SQLITE_BLOB ){
